public static int calculateTimeNeeded(int N) {
    if (N <= 1) return 0;
    if ((N & 1) == 1) {             // odd
        return N - 1;
    }
    if ((N & 3) == 0) {              // N is multiple of 4
        return N / 2;
    }
    return N;                        // even but not multiple of 4
}

public static int calculateTimeNeeded(int N) {
    if (N < 4) {
        return 0;
    }
    return 2 * (N - 3);
}

public static int calculateTimeNeeded(int N) {
    // Number of swaps needed to reverse the seating order while keeping the first person in place
    int swaps = (N - 1) / 2;          // floor((N-1)/2)
    int minutesPerSwap = N / 2;       // floor(N/2) minutes for each swap
    return swaps * minutesPerSwap;
}

