public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    int[] arr = nums.clone();
    java.util.Arrays.sort(arr);
    while (true) {
        java.util.List<Integer> perm = new java.util.ArrayList<>(n);
        for (int v : arr) {
            perm.add(v);
        }
        res.add(perm);
        int i = n - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) {
            i--;
        }
        if (i < 0) {
            break;
        }
        int j = n - 1;
        while (arr[j] <= arr[i]) {
            j--;
        }
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        int left = i + 1;
        int right = n - 1;
        while (left < right) {
            temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
    }
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    for (int len = first.length(); len >= 1; len--) {
        for (int start = 0; start <= first.length() - len; start++) {
            String cand = first.substring(start, start + len);
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!s.contains(cand) && !s.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the length of the shortest string to bound the search
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    // For each possible length starting from the maximum
    for (int len = minLen; len >= 1; len--) {
        // Collect all substrings of the given length from the first string
        List<String> candidates = new ArrayList<>();
        String first = strings.get(0);
        for (int i = 0; i <= first.length() - len; i++) {
            candidates.add(first.substring(i, i + len));
        }
        // Check each candidate
        for (String sub : candidates) {
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int i = 1; i < strings.size(); i++) {
                String cur = strings.get(i);
                if (!(cur.contains(sub) || cur.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLen = 0;
    for (String s : strings) {
        if (s == null) continue;
        maxLen = Math.max(maxLen, s.length());
    }

    // Check lengths from longest to shortest
    for (int len = maxLen; len >= 1; len--) {
        Map<String, Integer> freq = new HashMap<>();

        // Build frequency map of substrings of current length
        for (String s : strings) {
            if (s == null || s.length() < len) continue;
            Set<String> seen = new HashSet<>();
            for (int i = 0; i <= s.length() - len; i++) {
                String sub = s.substring(i, i + len);
                if (seen.add(sub)) { // add only once per string
                    freq.put(sub, freq.getOrDefault(sub, 0) + 1);
                }
            }
        }

        // Find if any substring or its reverse appears in at least two strings
        for (Map.Entry<String, Integer> entry : freq.entrySet()) {
            String sub = entry.getKey();
            int countSub = entry.getValue();
            String rev = new StringBuilder(sub).reverse().toString();

            if (sub.equals(rev)) {
                if (countSub >= 2) {
                    return len;
                }
            } else {
                int countRev = freq.getOrDefault(rev, 0);
                if (countSub + countRev >= 2) {
                    return len;
                }
            }
        }
    }

    return 0;
}

public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    java.util.Set<String> substrs = new java.util.HashSet<>();
    for (String s : strings) {
        if (s == null) continue;
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                substrs.add(s.substring(i, j));
            }
        }
    }
    int maxLen = 0;
    for (String sub : substrs) {
        String rev = new StringBuilder(sub).reverse().toString();
        if (substrs.contains(rev)) {
            int subLen = sub.length();
            if (subLen > maxLen) {
                maxLen = subLen;
            }
        }
    }
    return maxLen;
}

