public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinates to a unique key
    java.util.function.Function<int[], String> keyOf = coord -> java.util.Arrays.toString(coord);
    String startKey = keyOf.apply(start);
    String endKey = keyOf.apply(end);

    // Early exit if start and end are the same
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    for (int[] path : paths) {
        // Each path is assumed to contain two coordinates appended together: first n elements, next n elements
        if (path.length != 2 * n) {
            // Skip malformed path entries
            continue;
        }
        int[] coordA = java.util.Arrays.copyOfRange(path, 0, n);
        int[] coordB = java.util.Arrays.copyOfRange(path, n, 2 * n);
        String keyA = keyOf.apply(coordA);
        String keyB = keyOf.apply(coordB);

        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    // Perform BFS to find if end is reachable from start
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (visited.add(neighbor)) {
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

