public static String convertDatesToWeekdays(String date) {
    java.time.format.DateTimeFormatter formatter = 
        java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.ENGLISH);
    java.time.LocalDate localDate = java.time.LocalDate.parse(date, formatter);
    int day = localDate.getDayOfMonth();
    String monthName = localDate.getMonth()
                                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    String year = String.valueOf(localDate.getYear());
    String weekday = localDate.getDayOfWeek()
                              .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return monthName + " " + day + ", " + year + " is a " + weekday;
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return "";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "";
    }
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    java.time.LocalDate ld = java.time.LocalDate.of(year, month, day);

    String monthName = ld.getMonth()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    String weekday = ld.getDayOfWeek()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

    return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
}

