public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k == 0) {
        return false;
    }
    int[] remCount = new int[k];
    for (int num : arr) {
        int r = Math.floorMod(num, k);
        remCount[r]++;
    }
    if (remCount[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        int opposite = k - r;
        if (r == opposite) { // k is even and r == k/2
            if (remCount[r] % 2 != 0) {
                return false;
            }
        } else {
            if (remCount[r] != remCount[opposite]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // ensure non-negative remainder
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check pairs of remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) {
            // When k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    if (freq[0] % 2 != 0) return false;
    int max = k / 2;
    for (int r = 1; r <= max; r++) {
        if (k % 2 == 0 && r == max) { // when k is even, handle remainder k/2 separately
            if (freq[r] % 2 != 0) return false;
        } else {
            if (freq[r] != freq[k - r]) return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) return false; // invalid divisor
    int[] count = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) rem += k;
        count[rem]++;
    }
    // Check remainder 0
    if (count[0] % 2 != 0) return false;
    // Check other remainders
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) { // when k is even and i is k/2
            if (count[i] % 2 != 0) return false;
        } else {
            if (count[i] != count[k - i]) return false;
        }
    }
    return true;
}

