public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.List[n];
    for (int i = 0; i < n; i++) graph[i] = new java.util.ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] res = new int[1];
    dfs(0, -1, graph, hasApple, res);
    return res[0];
}

private boolean dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple, int[] res) {
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        if (dfs(nei, node, graph, hasApple, res)) {
            res[0] += 2;
            has = true;
        }
    }
    return has;
}

