private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
        boolean has = hasApple[node];
        for (int child : graph[node]) {
            if (child == parent) continue;
            boolean childHas = dfs(child, node, graph, hasApple, time);
            if (childHas) {
                time[0] += 2;
                has = true;
            }
        }
        return has;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        adj[u].add(v);
        adj[v].add(u);
    }
    boolean[] visited = new boolean[n];
    int[] total = new int[1];
    dfs(0, adj, visited, hasApple, total);
    return total[0];
}

private boolean dfs(int node, java.util.List<Integer>[] adj, boolean[] visited, boolean[] hasApple, int[] total) {
    visited[node] = true;
    boolean has = hasApple[node];
    for (int nei : adj[node]) {
        if (!visited[nei]) {
            boolean childHas = dfs(nei, adj, visited, hasApple, total);
            if (childHas) {
                total[0] += 2;
                has = true;
            }
        }
    }
    return has;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Step 1-3: smallest to largest
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
        // Step 4-6: largest to smallest
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    TreeMap<Character, Integer> map = new TreeMap<>();
    for (char ch : s.toCharArray()) {
        map.merge(ch, 1, Integer::sum);
    }

    StringBuilder res = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending phase
        Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        res.append(last);
        // decrement count
        int cnt = entry.getValue() - 1;
        if (cnt == 0) {
            map.remove(last);
        } else {
            map.put(last, cnt);
        }

        while (true) {
            entry = map.higherEntry(last);
            if (entry == null) break;
            last = entry.getKey();
            res.append(last);
            cnt = entry.getValue() - 1;
            if (cnt == 0) {
                map.remove(last);
            } else {
                map.put(last, cnt);
            }
        }

        if (map.isEmpty()) break;

        // Descending phase
        entry = map.lastEntry();
        last = entry.getKey();
        res.append(last);
        cnt = entry.getValue() - 1;
        if (cnt == 0) {
            map.remove(last);
        } else {
            map.put(last, cnt);
        }

        while (true) {
            entry = map.lowerEntry(last);
            if (entry == null) break;
            last = entry.getKey();
            res.append(last);
            cnt = entry.getValue() - 1;
            if (cnt == 0) {
                map.remove(last);
            } else {
                map.put(last, cnt);
            }
        }
    }
    return res.toString();
}

