public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            for (int s = totalSum; s >= num; s--) {
                if (dp[k - 1][s - num]) dp[k][s] = true;
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int half = n / 2;

    // store sums for each count in left half
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] leftSums = new java.util.ArrayList[half + 1];
    for (int i = 0; i <= half; i++) {
        leftSums[i] = new java.util.ArrayList<>();
    }
    int leftSize = half;
    int leftMaskLimit = 1 << leftSize;
    for (int mask = 0; mask < leftMaskLimit; mask++) {
        int cnt = Integer.bitCount(mask);
        int sum = 0;
        for (int i = 0; i < leftSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
            }
        }
        leftSums[cnt].add(sum);
    }

    // store sums for each count in right half
    int rightSize = n - leftSize;
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] rightSums = new java.util.ArrayList[rightSize + 1];
    for (int i = 0; i <= rightSize; i++) {
        rightSums[i] = new java.util.ArrayList<>();
    }
    int rightMaskLimit = 1 << rightSize;
    for (int mask = 0; mask < rightMaskLimit; mask++) {
        int cnt = Integer.bitCount(mask);
        int sum = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[leftSize + i];
            }
        }
        rightSums[cnt].add(sum);
    }

    // convert right lists to hash sets for fast lookup
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] rightSet = new java.util.HashSet[rightSize + 1];
    for (int i = 0; i <= rightSize; i++) {
        rightSet[i] = new java.util.HashSet<>(rightSums[i]);
    }

    // try all possible subset sizes k (1 <= k < n)
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        int targetSum = (totalSum * k) / n;

        int maxLeft = Math.min(k, leftSize);
        for (int leftCnt = 0; leftCnt <= maxLeft; leftCnt++) {
            int rightCnt = k - leftCnt;
            if (rightCnt > rightSize) continue;
            java.util.Set<Integer> rightSetExpected = rightSet[rightCnt];
            for (int leftSum : leftSums[leftCnt]) {
                int needed = targetSum - leftSum;
                if (rightSetExpected.contains(needed)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    java.util.ArrayList<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            java.util.Set<Integer> prev = dp.get(k - 1);
            java.util.Set<Integer> cur = dp.get(k);
            for (int sum : prev) {
                cur.add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

