    int totalSum = 0;
    for (int num : nums) totalSum += num;

    @SuppressWarnings("unchecked")
    Set<Integer>[] dp = new HashSet[n + 1];
    for (int k = 0; k <= n; k++) dp[k] = new HashSet<>();
    dp[0].add(0);

    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if (totalSum * k % n != 0) continue;
        int target = totalSum * k / n;
        if (dp[k].contains(target)) return true;
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;
    int half = n / 2;
    int m = half;
    Map<Integer, Set<Integer>> map1 = new HashMap<>();
    for (int mask = 0; mask < (1 << m); mask++) {
        int sum = 0;
        int sz = 0;
        for (int i = 0; i < m; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                sz++;
            }
        }
        map1.computeIfAbsent(sz, k -> new HashSet<>()).add(sum);
    }
    int n2 = n - half;
    Map<Integer, Set<Integer>> map2 = new HashMap<>();
    for (int mask = 0; mask < (1 << n2); mask++) {
        int sum = 0;
        int sz = 0;
        for (int i = 0; i < n2; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[half + i];
                sz++;
            }
        }
        map2.computeIfAbsent(sz, k -> new HashSet<>()).add(sum);
    }
    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        for (Map.Entry<Integer, Set<Integer>> e1 : map1.entrySet()) {
            int sz1 = e1.getKey();
            int sz2 = k - sz1;
            if (sz2 < 0) continue;
            Set<Integer> set2 = map2.get(sz2);
            if (set2 == null) continue;
            for (int sum1 : e1.getValue()) {
                int needed = target - sum1;
                if (set2.contains(needed)) return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int prev2 = cost[0]; // min cost to reach step 0
    int prev1 = cost[1]; // min cost to reach step 1

    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }

    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prevTwo = 0; // cost to reach step i-2
    int prevOne = 0; // cost to reach step i-1
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prevOne + cost[i - 1], prevTwo + cost[i - 2]);
        prevTwo = prevOne;
        prevOne = curr;
    }
    return prevOne;
}

public int minCostClimbingStairs(int[] cost) {
