public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;
    int cur = 0;

    // Build the first window
    for (int i = 0; i < k; i++) {
        cur = (cur << 1) | (s.charAt(i) - '0');
    }
    if (!seen[cur]) {
        seen[cur] = true;
        count++;
    }

    int mask = total - 1;
    for (int i = 1; i <= n - k; i++) {
        cur = ((cur << 1) & mask) | (s.charAt(i + k - 1) - '0');
        if (!seen[cur]) {
            seen[cur] = true;
            count++;
            if (count == total) return true;
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    int total = 1 << k;
    if (s.length() < k) return false;
    boolean[] seen = new boolean[total];
    int mask = 0;
    int maskK = total - 1;
    int seenCount = 0;
    for (int i = 0; i < s.length(); i++) {
        mask = ((mask << 1) & maskK) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == total) return true;
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int required = 1 << k;
    if (n < required) return false;
    boolean[] seen = new boolean[required];
    int mask = 0;
    int maskLimit = required - 1;
    for (int i = 0; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[mask] = true;
        }
    }
    for (boolean present : seen) {
        if (!present) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }
    int total = 1 << k;          // Number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // Mask to keep only k bits
    int window = 0;              // Current window value encoded as integer
    int uniqueCount = 0;         // Count of distinct patterns seen

    for (int i = 0; i < s.length(); i++) {
        // Shift left by one bit and add the new bit (0 or 1)
        window = ((window << 1) & mask) | (s.charAt(i) - '0');

        if (i >= k - 1) {        // Only start marking after the first full window
            if (!seen[window]) {
                seen[window] = true;
                uniqueCount++;
                if (uniqueCount == total) {
                    return true;  // All patterns found
                }
            }
        }
    }
    return false; // Not all patterns were found
}

public boolean hasAllCodes(String s, int k) {
