    if (n % 2 == 0) {
        return half * half;
    } else {
        return half * (half + 1);
    }
}

public int minOperations(int n) {
    int m = (n + 1) / 2;          // number of indices that are below the target value n
    return m * (n - m);          // total units needed to bring them up to n
}

public int minOperations(int n) {
    int s = (n + 1) / 2;
    return s * (n - s);
}

public int minOperations(int n) {
    if (n % 2 == 0) {
        int half = n / 2;
        return half * half;
    } else {
        return ((n * n) - 1) / 4;
    }
}

