public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    int maxAbs = Math.abs(maxSoFar);
    int minAbs = Math.abs(minSoFar);
    return Math.max(maxAbs, minAbs);
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int maxCurrent = nums[0];
    int maxGlobal = nums[0];
    int minCurrent = nums[0];
    int minGlobal = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];

        // For maximum subarray sum
        maxCurrent = Math.max(val, maxCurrent + val);
        maxGlobal = Math.max(maxGlobal, maxCurrent);

        // For minimum subarray sum
        minCurrent = Math.min(val, minCurrent + val);
        minGlobal = Math.min(minGlobal, minCurrent);
    }

    int maxAbsSum = Math.max(maxGlobal, -minGlobal);
    return maxAbsSum;
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int currentMax = 0;
    int maxSum = Integer.MIN_VALUE;
    int currentMin = 0;
    int minSum = Integer.MAX_VALUE;

    for (int num : nums) {
        currentMax = Math.max(currentMax + num, num);
        maxSum = Math.max(maxSum, currentMax);

        currentMin = Math.min(currentMin + num, num);
        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(maxSum, -minSum);
}

