public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[50];
    int size = 0;
    fib[size++] = 1;
    fib[size++] = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
        if (remaining == 0) {
            break;
        }
    }
    return count;
}

