public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[47];
    fib[0] = 1;
    fib[1] = 1;
    int idx = 2;
    while (true) {
        long next = (long) fib[idx - 1] + fib[idx - 2];
        if (next > k) break;
        fib[idx] = (int) next;
        idx++;
    }
    int count = 0;
    for (int i = idx - 1; i >= 0 && k > 0; i--) {
        if (k >= fib[i]) {
            k -= fib[i];
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers less than or equal to k
    int[] fibs = new int[50];
    fibs[0] = 1;
    fibs[1] = 1;
    int size = 2;
    while (true) {
        int next = fibs[size - 1] + fibs[size - 2];
        if (next > k) break;
        fibs[size++] = next;
    }

    int count = 0;
    int remaining = k;
    // Greedy: repeatedly subtract the largest Fibonacci number <= remaining
    while (remaining > 0) {
        int i = size - 1;
        while (fibs[i] > remaining) i--;
        remaining -= fibs[i];
        count++;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50];
    int countFibs = 0;
    int a = 1, b = 1;
    fibs[countFibs++] = a;      // F1
    while (b <= k) {
        fibs[countFibs++] = b;  // F2 onward
        int c = a + b;
        a = b;
        b = c;
    }

    // Greedy selection from largest to smallest
    int remaining = k;
    int result = 0;
    for (int i = countFibs - 1; i >= 0 && remaining > 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            result++;
        }
    }
    return result;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();

    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }

    int smallSize = small.size();
    if (k <= smallSize) {
        return small.get(k - 1);
    }

    // large currently contains factors in descending order
    Collections.reverse(large);
    int remaining = k - smallSize;
    if (remaining <= large.size()) {
        return large.get(remaining - 1);
    }

    return -1;
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    int countSmall = small.size();
    int countLarge = large.size();
    int total = countSmall + countLarge;
    if (k > total) {
        return -1;
    }
    if (k <= countSmall) {
        return small.get(k - 1);
    } else {
        int idxLarge = countLarge - (k - countSmall);
        return large.get(idxLarge);
    }
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        small.add(large.get(i));
    }
    return k <= small.size() ? small.get(k - 1) : -1;
}

