    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int pair = n / i;
            if (pair != i) {
                large.add(pair);
            }
        }
    }
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        java.util.Collections.reverse(large);
        return large.get(k - small.size() - 1);
    }
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(last - c) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

