}

public String makeGood(String s) {
    char[] stack = new char[s.length()];
    int ptr = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (ptr > 0 && Math.abs(c - stack[ptr - 1]) == 32) {
            ptr--;  // remove the adjacent bad pair
        } else {
            stack[ptr++] = c;
        }
    }
    return new String(stack, 0, ptr);
}

