public int maxUniqueSplit(String s) {
    int n = s.length();
    int best = 0;
    java.util.ArrayDeque<Integer> idxStack = new java.util.ArrayDeque<>();
    java.util.ArrayDeque<java.util.Set<String>> setStack = new java.util.ArrayDeque<>();
    idxStack.push(0);
    setStack.push(new java.util.HashSet<String>());
    while (!idxStack.isEmpty()) {
        int idx = idxStack.pop();
        java.util.Set<String> used = setStack.pop();
        if (idx == n) {
            if (used.size() > best) best = used.size();
            continue;
        }
        for (int end = idx + 1; end <= n; end++) {
            String sub = s.substring(idx, end);
            if (!used.contains(sub)) {
                java.util.Set<String> newUsed = new java.util.HashSet<String>(used);
                newUsed.add(sub);
                idxStack.push(end);
                setStack.push(newUsed);
            }
        }
    }
    return best;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] best = new int[]{0};
    dfs(0, s, new java.util.HashSet<>(), best);
    return best[0];
}

private void dfs(int idx, String s, java.util.Set<String> used, int[] best) {
    int n = s.length();
    if (idx == n) {
        if (used.size() > best[0]) {
            best[0] = used.size();
        }
        return;
    }
    for (int end = idx + 1; end <= n; end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, s, used, best);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    return dfs(s, 0, new java.util.HashSet<>());
}

private int dfs(String s, int start, java.util.Set<String> used) {
    if (start == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String sub = s.substring(start, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = 1 + dfs(s, end, used);
            if (res > max) {
                max = res;
            }
            used.remove(sub);
        }
    }
    return max;
}

public static int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    Set<String> seen = new HashSet<>();
    return dfs(s, 0, seen);
}

private static int dfs(String s, int start, Set<String> seen) {
    if (start == s.length()) {
        return 0;
    }

    int max = 0;
    for (int i = start + 1; i <= s.length(); i++) {
        String part = s.substring(start, i);
        if (!seen.contains(part)) {
            seen.add(part);
            int count = 1 + dfs(s, i, seen);
            if (count > max) {
                max = count;
            }
            seen.remove(part);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << (n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.Set<String> set = new java.util.HashSet<>();
        int start = 0;
        int count = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String sub = s.substring(start, i + 1);
                if (!set.add(sub)) {
                    valid = false;
                    break;
                }
                count++;
                start = i + 1;
            }
        }
        if (!valid) {
            continue;
        }
        String lastSub = s.substring(start);
        if (!set.add(lastSub)) {
            continue;
        }
        count++; // include the last substring
        if (count > max) {
            max = count;
        }
    }
    return max;
}

