public String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    java.util.Arrays.fill(chars, 'a'); // initialize with 'a' (value 1)
    int remaining = k - n; // we have already used value n for all 'a's
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max increase from 'a' to 'z'
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    char[] res = new char[n];
    for (int i = 0; i < n; i++) {
        res[i] = 'a';
    }
    int remaining = k - n; // extra value above the minimum 'a's
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        res[i] = (char)(res[i] + add);
        remaining -= add;
    }
    return new String(res);
}

