public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        ones = (ones ^ num) & ~twos;
        twos = (twos ^ num) & ~ones;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if ((num & (1 << i)) != 0) {
                bitCount[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if (bitCount[i] % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitSum = 0;
        for (int num : nums) {
            bitSum += (num >> i) & 1;
        }
        if ((bitSum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
