public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int ones = 0;   // bits that have appeared 1 time modulo 3
    int twos = 0;   // bits that have appeared 2 times modulo 3
    for (int num : nums) {
        // Update twos with bits that have appeared twice
        twos |= ones & num;
        // Update ones with bits that have appeared once
        ones ^= num;
        // Bits that have appeared three times
        int threes = ones & twos;
        // Remove bits that have appeared three times from ones and twos
        ones &= ~threes;
        twos &= ~threes;
    }
    return ones; // only the bit pattern of the unique number
}

private static void generateStepping(long current, int low, int high, java.util.List<Integer> result) {
    if (current > high) {
