        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0) continue;
            int curWays = dp[mask][last];
            if (curWays == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!can[last][next]) continue;
                dp[mask | (1 << next)][next] += curWays;
            }
        }
    }
    int finalMask = totalMasks - 1;
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[finalMask][i];
    }
    return result;
}

