public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int index = 0;
    for (int k = 0; k < m + n - 1; k++) {
        if (k % 2 == 0) {
            // even diagonal: start from the bottom of the diagonal
            int i = Math.min(k, m - 1);
            while (i >= 0 && k - i < n) {
                res[index++] = mat[i][k - i];
                i--;
            }
        } else {
            // odd diagonal: start from the top of the diagonal
            int j = Math.min(k, n - 1);
            while (j >= 0 && k - j < m) {
                res[index++] = mat[k - j][j];
                j--;
            }
        }
    }
    return res;
}

