        int row = Math.min(k, m - 1);
        int col = k - row;
        java.util.ArrayList<Integer> temp = new java.util.ArrayList<>();
        while (row >= 0 && col < n) {
            temp.add(mat[row][col]);
            row--;
            col++;
        }
        if (k % 2 == 0) {
            for (int i = temp.size() - 1; i >= 0; i--) {
                result[pos++] = temp.get(i);
            }
        } else {
            for (int val : temp) {
                result[pos++] = val;
            }
        }
    }
    return result;
}

