public static List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>(n);
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if ((long) cur * 10 <= n) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur + 1 <= n) {
                cur += 1;
            } else {
                while ((cur / 10) % 10 == 9) {
                    cur /= 10;
                }
                cur = cur / 10 + 1;
            }
        }
    }
    return result;
}

