public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, res);
    }
    return res;
}

private static void dfs(int curr, int n, List<Integer> res) {
    if (curr > n) return;
    res.add(curr);
    for (int d = 0; d <= 9; d++) {
        long next = (long) curr * 10 + d;
        if (next > n) break;
        dfs((int) next, n, res);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        return 0;
    }
    java.util.Map<Integer, Integer> frequency = new java.util.HashMap<>();
    for (int num : nums) {
        frequency.put(num, frequency.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

